def get_all_cricket_players() -> List[Dict[str, Any]]:
    return CRICKET_PLAYERS_DATA

def get_cricket_player_by_id(player_id: str) -> Optional[Dict[str, Any]]:
    for p in CRICKET_PLAYERS_DATA:
        if p['id'] == player_id:
            return p
    return None

def get_player_by_id(player_id: str) -> Optional[CricketPlayer]:
    raw = get_cricket_player_by_id(player_id)
    if raw:
        return CricketPlayer(**raw)
    return None
